assert len(cases)==80
payload={'suite_version':'0.1-proposed','purpose':'Behavioral acceptance contract for an agent-assisted theory design tool; not a ratified Morphisms specification.','baseline':{'graph_revision':12,'existing_engine_tests_passed':25,'current_supported_fragment':'exclusive_actor on bounded after_attempt_ended traces'},'notation':{'depends_on':'dependent -> prerequisite','None':'unbounded upper cardinality bound in this JSON represented by null','phase':'P1 next implementation target; P2 later explicit structured fragment; agent cases require a blind agent evaluation'},'cases':cases}
(ROOT/'cases.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
lines=['# Acceptance cases — 80 proposed scenarios','', 'These are behavioral specifications, not executable engine fixtures. See CONTRACT.md for semantics and IMPLEMENTER.md for conversion and grading. No case is claimed to pass merely because this document exists.','']
for c in cases:
 lines += [f"## {c['id']} — {c['title']}",'',f"**Group:** {c['group']} · **Mechanism:** {c['mechanism']} · **Phase:** {c['phase']}",'','**Given**','', '```json',json.dumps(c['arrange'],ensure_ascii=False,indent=2),'```','','**When**','']+[f'{i+1}. {a}' for i,a in enumerate(c['actions'])]+['','**Then**','','```json',json.dumps(c['assertions'],ensure_ascii=False,indent=2),'```','','**Must not**','']+['- '+x for x in c['must_not']]
 if c['assumptions']:lines+=['','**Fixture assumptions**','']+['- '+x for x in c['assumptions']]
 lines+=['']
(ROOT/'CASES.md').write_text('\n'.join(lines))
print(f'Wrote {len(cases)} cases; groups:',{g:sum(c['group']==g for c in cases) for g in sorted(set(c['group'] for c in cases))})
